import re
import datetime
from collections import defaultdict

import pandas as pd

_NUM_RE = re.compile(r'^[+-]?\d+(\.\d{1,2})?$')
_DATE_RE = re.compile(r'^\d{4}-\d{2}-\d{2}$')
_VALID_CURRENCIES = {'USD', 'EUR', 'GBP'}


def run(inputs: dict) -> dict:
    df = inputs['raw_payments']

    results = []

    for _, row in df.iterrows():
        row_num = row['row_num']
        payment_id = row['payment_id']
        account_id = row['account_id']
        amount_txt = row['amount_txt']
        currency = row['currency']
        pay_date_txt = row['pay_date_txt']

        reason = None
        trimmed_id = None
        parsed_amount = None
        parsed_currency = None
        parsed_date = None

        # R1 MISSING_ID
        if pd.isna(payment_id):
            reason = 'MISSING_ID'
        else:
            trimmed_id = str(payment_id).strip()
            if trimmed_id == '':
                reason = 'MISSING_ID'

        # R2 BAD_AMOUNT
        if reason is None:
            if pd.isna(amount_txt):
                reason = 'BAD_AMOUNT'
            else:
                trimmed_amt = str(amount_txt).strip()
                if not _NUM_RE.match(trimmed_amt):
                    reason = 'BAD_AMOUNT'
                else:
                    parsed_amount = float(trimmed_amt)

        # R3 NON_POSITIVE
        if reason is None:
            if parsed_amount <= 0:
                reason = 'NON_POSITIVE'

        # R4 BAD_CURRENCY
        if reason is None:
            if pd.isna(currency):
                reason = 'BAD_CURRENCY'
            else:
                trimmed_cur = str(currency).strip().upper()
                if trimmed_cur not in _VALID_CURRENCIES:
                    reason = 'BAD_CURRENCY'
                else:
                    parsed_currency = trimmed_cur

        # R5 BAD_DATE
        if reason is None:
            if pd.isna(pay_date_txt):
                reason = 'BAD_DATE'
            else:
                trimmed_date = str(pay_date_txt).strip()
                if not _DATE_RE.match(trimmed_date):
                    reason = 'BAD_DATE'
                else:
                    try:
                        parsed_date = datetime.datetime.strptime(
                            trimmed_date, '%Y-%m-%d'
                        ).date()
                    except ValueError:
                        reason = 'BAD_DATE'

        results.append({
            'row_num': row_num,
            'account_id': account_id,
            'reason': reason,
            'trimmed_id': trimmed_id,
            'parsed_amount': parsed_amount,
            'parsed_currency': parsed_currency,
            'parsed_date': parsed_date,
        })

    # R6 DUPLICATE: among rows that passed R1-R5, group by trimmed payment_id
    passed = [r for r in results if r['reason'] is None]
    groups = defaultdict(list)
    for r in passed:
        groups[r['trimmed_id']].append(r)

    for key, group in groups.items():
        if len(group) > 1:
            min_row_num = min(g['row_num'] for g in group)
            for g in group:
                if g['row_num'] != min_row_num:
                    g['reason'] = 'DUPLICATE'

    valid_rows = []
    reject_rows = []

    for r in results:
        if r['reason'] is None:
            valid_rows.append({
                'payment_id': r['trimmed_id'],
                'account_id': r['account_id'],
                'amount': r['parsed_amount'],
                'currency': r['parsed_currency'],
                'pay_date': r['parsed_date'],
            })
        else:
            reject_rows.append({
                'row_num': r['row_num'],
                'reject_reason': r['reason'],
            })

    valid_df = pd.DataFrame(
        valid_rows,
        columns=['payment_id', 'account_id', 'amount', 'currency', 'pay_date']
    )
    reject_df = pd.DataFrame(
        reject_rows,
        columns=['row_num', 'reject_reason']
    )

    return {
        'valid_payments': valid_df,
        'payment_rejects': reject_df,
    }
